package gitrepo

// TEMPORARY INSTRUMENTATION - delete before commit.
// Counts repository opens and filesystem read traffic on the git-dir FS.
// Enabled by setting ENTIRE_PERF_FILE=<path>; a summary is flushed there.

import (
	"fmt"
	"os"
	"sync/atomic"
	"time"

	"github.com/go-git/go-billy/v6"
)

var (
	perfOpens     atomic.Int64
	perfFileOpens atomic.Int64
	perfReads     atomic.Int64
	perfBytes     atomic.Int64
	perfStarted   atomic.Bool
	perfStart     = time.Now()
)

func perfEnabled() bool { return os.Getenv("ENTIRE_PERF_FILE") != "" }

// perfFlusher writes the running totals to ENTIRE_PERF_FILE every 20ms so the
// last write approximates the process's final state (Go has no atexit hook).
func perfMaybeStartFlusher() {
	if !perfEnabled() || perfStarted.Swap(true) {
		return
	}
	path := os.Getenv("ENTIRE_PERF_FILE")
	go func() {
		for {
			line := fmt.Sprintf("opens=%d file_opens=%d reads=%d bytes=%d elapsed_ms=%d\n",
				perfOpens.Load(), perfFileOpens.Load(), perfReads.Load(),
				perfBytes.Load(), time.Since(perfStart).Milliseconds())
			_ = os.WriteFile(path, []byte(line), 0o600)
			time.Sleep(20 * time.Millisecond)
		}
	}()
}

type countingFS struct {
	billy.Filesystem
}

func wrapCounting(fs billy.Filesystem) billy.Filesystem {
	if !perfEnabled() {
		return fs
	}
	return &countingFS{Filesystem: fs}
}

func (fs *countingFS) Open(name string) (billy.File, error) {
	f, err := fs.Filesystem.Open(name)
	if err != nil {
		return f, err
	}
	perfFileOpens.Add(1)
	return &countingFile{File: f}, nil
}

func (fs *countingFS) OpenFile(name string, flag int, perm os.FileMode) (billy.File, error) {
	f, err := fs.Filesystem.OpenFile(name, flag, perm)
	if err != nil {
		return f, err
	}
	perfFileOpens.Add(1)
	return &countingFile{File: f}, nil
}

type countingFile struct {
	billy.File
}

func (f *countingFile) Read(p []byte) (int, error) {
	n, err := f.File.Read(p)
	perfReads.Add(1)
	perfBytes.Add(int64(n))
	return n, err
}

func (f *countingFile) ReadAt(p []byte, off int64) (int, error) {
	n, err := f.File.ReadAt(p, off)
	perfReads.Add(1)
	perfBytes.Add(int64(n))
	return n, err
}

