38	// parseTraceEntry parses a JSON log line into a traceEntry.
39	// Returns nil if the line is not valid JSON or is not a trace entry (msg != "perf").
40	func parseTraceEntry(line string) *traceEntry {
41		// Cheap pre-filter: skip full JSON parse for lines that can't be perf entries.
42		// Most lines in the shared log file are non-perf, so this avoids the
43		// marshalling cost for the common reject path.
44		if !strings.Contains(line, `"msg":"perf"`) {
45			return nil
46		}
47	
48		var raw map[string]json.RawMessage
49		if err := json.Unmarshal([]byte(line), &raw); err != nil {
50			return nil
51		}
52	
53		// Verify msg == "perf" after full parse (the pre-filter could match substrings)
54		var msg string
55		if msgRaw, ok := raw["msg"]; !ok {
56			return nil
57		} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
58			return nil
59		}
60	
61		entry := &traceEntry{}
62	
63		// Best-effort field extraction: missing or mistyped fields keep their
64		// zero values rather than discarding the entire entry.
65		if opRaw, ok := raw["op"]; ok {
66			_ = json.Unmarshal(opRaw, &entry.Op) //nolint:errcheck // best-effort
67		}
68		if dRaw, ok := raw["duration_ms"]; ok {
69			_ = json.Unmarshal(dRaw, &entry.DurationMs) //nolint:errcheck // best-effort
70		}
71		if errRaw, ok := raw["error"]; ok {
72			_ = json.Unmarshal(errRaw, &entry.Error) //nolint:errcheck // best-effort
73		}
74	
75		// Extract time
76		if tRaw, ok := raw["time"]; ok {
77			var ts string
78			if err := json.Unmarshal(tRaw, &ts); err == nil {
79				if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
80					entry.Time = parsed
81				}
82			}
83		}
84	
85		// Extract steps by finding keys matching "steps.*_ms"
86		stepDurations := make(map[string]int64)
87		stepErrors := make(map[string]bool)
88	
89		for key, val := range raw {
90			if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
91				name := strings.TrimPrefix(key, "steps.")
92				name = strings.TrimSuffix(name, "_ms")
93	
94				var ms int64
95				if err := json.Unmarshal(val, &ms); err == nil {
96					stepDurations[name] = ms
97				}
98			} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
99				name := strings.TrimPrefix(key, "steps.")
100				name = strings.TrimSuffix(name, "_err")
101	
102				var errFlag bool
103				if err := json.Unmarshal(val, &errFlag); err == nil {
104					stepErrors[name] = errFlag
105				}
106			}
107		}
