119	func buildTraceSteps(stepDurations map[string]int64, stepErrors map[string]bool) []traceStep {
120		nodes := make(map[string]*traceStepNode, len(stepDurations))
121		for name, ms := range stepDurations {
122			nodes[name] = &traceStepNode{
123				step: traceStep{
124					Name:       name,
125					DurationMs: ms,
126					Error:      stepErrors[name],
127				},
128			}
129		}
130	
131		roots := make([]*traceStepNode, 0, len(nodes))
132		for name, node := range nodes {
133			parentName, ok := traceStepParent(name, stepDurations)
134			if !ok {
135				roots = append(roots, node)
136				continue
137			}
138			nodes[parentName].children = append(nodes[parentName].children, node)
139		}
140	
141		return traceStepNodesToSteps(roots, "")
142	}
