144	func traceStepParent(name string, allSteps map[string]int64) (string, bool) {
145		candidate := name
146		for {
147			idx := strings.LastIndex(candidate, ".")
148			if idx < 0 {
149				return "", false
150			}
151			candidate = candidate[:idx]
152			if _, ok := allSteps[candidate]; ok {
153				return candidate, true
154			}
155		}
156	}
