// buildCodexTranscript produces roughly targetBytes of Codex-rollout-shaped
// JSONL: a mix of large tool outputs (the realistic bulk) and reasoning items
// carrying base64 encrypted_content (the entropy-layer pathological case).
func buildCodexTranscript(targetBytes int) []byte {
	rng := rand.New(rand.NewSource(42))
	var buf bytes.Buffer
	blob := make([]byte, 24*1024)
	for buf.Len() < targetBytes {
		switch rng.Intn(3) {
		case 0:
			rng.Read(blob)
			line, _ := json.Marshal(map[string]any{
				"type": "response_item",
				"payload": map[string]any{
					"type": "reasoning",
					"content": []map[string]any{{
						"type":              "reasoning_text",
						"encrypted_content": base64.StdEncoding.EncodeToString(blob),
					}},
				},
			})
			buf.Write(line)
		case 1:
			// Large tool output: realistic prose-ish payload, low entropy.
			text := bytes.Repeat([]byte("the quick brown fox jumps over the lazy dog 0123456789 "), 400)
			line, _ := json.Marshal(map[string]any{
				"type": "response_item",
				"payload": map[string]any{
					"type":   "function_call_output",
					"output": string(text),
				},
			})
			buf.Write(line)
		default:
			line, _ := json.Marshal(map[string]any{
				"type": "response_item",
				"payload": map[string]any{
					"type":    "message",
					"role":    "assistant",
					"content": []map[string]any{{"type": "output_text", "text": bytes.NewBuffer(nil).String() + "some assistant reply with a token sk-abc123 and an email a@b.com"}},
				},
			})
			buf.Write(line)
		}
		buf.WriteByte('\n')
	}
	return buf.Bytes()
}

