// parallelJSONL redacts JSONL by splitting on lines and processing shards
// concurrently. Lines are independent under the stateless regex redactor, so
// output must be byte-identical to the sequential path.
func parallelJSONL(content string, shards int) string {
	lines := strings.Split(content, "\n")
	if shards < 1 {
		shards = 1
	}
	per := (len(lines) + shards - 1) / shards
	out := make([]string, shards)
	var wg sync.WaitGroup
	for s := 0; s < shards; s++ {
		lo := s * per
		hi := min(lo+per, len(lines))
		if lo >= hi {
			continue
		}
		wg.Add(1)
		go func(idx, lo, hi int) {
			defer wg.Done()
			r, err := redact.JSONLContent(strings.Join(lines[lo:hi], "\n"))
			if err != nil {
				r = strings.Join(lines[lo:hi], "\n")
			}
			out[idx] = r
		}(s, lo, hi)
	}
	wg.Wait()
	var b strings.Builder
	first := true
	for _, o := range out {
		if o == "" {
			continue
		}
		if !first {
			b.WriteByte('\n')
		}
		b.WriteString(o)
		first = false
	}
	return b.String()
}

