func jsonlContentImpl(content string, redactor func(string) string) (string, error) {
	if result, handled, err := redactSingleJSONValue(content, redactor); handled {
		return result, err
	}
	return redactJSONLLines(strings.Split(content, "\n"), redactor)
}

// redactSingleJSONValue handles the case where the whole content is one JSON
// value (e.g. pretty-printed single objects like OpenCode export) so
// field-aware redaction is used instead of falling back to entropy-based
// detection on raw text lines, which would corrupt high-entropy identifiers.
//
// Uses a streaming decoder to avoid copying the full content into []byte. After
// decoding, a second Decode confirms EOF — if that succeeds the content is JSONL
// (multiple values) and handled is false so the caller processes it line by line.
func redactSingleJSONValue(content string, redactor func(string) string) (result string, handled bool, err error) {
	trimmed := strings.TrimSpace(content)
	if len(trimmed) == 0 {
		return "", false, nil
	}
	dec := json.NewDecoder(strings.NewReader(trimmed))
	var parsed any
	if decErr := dec.Decode(&parsed); decErr != nil || !isSingleJSONValue(dec) {
		return "", false, nil
	}
	result, err = applyJSONReplacements(content, collectJSONLReplacements(parsed, redactor))
	if err != nil {
		return "", true, err
	}
	return result, true, nil
}

// redactJSONLLines redacts each line independently and rejoins them with "\n".
//
// Every line is handled in isolation: no state carries between lines, which is
// what makes sharding across goroutines (jsonlContentConcurrent) produce
// byte-identical output to a sequential pass. Keep it that way — a redactor or
// line rule that depended on earlier lines would silently break that guarantee.
func redactJSONLLines(lines []string, redactor func(string) string) (string, error) {
	var b strings.Builder
	for i, line := range lines {
		if i > 0 {
			b.WriteByte('\n')
		}
		lineTrimmed := strings.TrimSpace(line)
		if lineTrimmed == "" {
			b.WriteString(line)
			continue
		}
		var parsed any
		if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
			b.WriteString(redactor(line))
			continue
		}
		result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed, redactor))
		if err != nil {
			return "", err
		}
		b.WriteString(result)
	}
	return b.String(), nil
}

// Sharding parameters for jsonlContentConcurrent.
//
// The win here is not purely parallelism: redaction cost per byte climbs with
// input size (allocation and GC pressure over one large buffer), so cutting the
// content into small pieces is cheaper per byte *and* lets pieces run
// concurrently. Measured on a 20MB Codex transcript: 43s sequential vs 2.1s
// across 12 shards. Hence a byte-sized shard target rather than one shard per
// core, with worker count bounding actual concurrency.
const (
	// jsonlConcurrentMinBytes is the content size below which sharding's
	// overhead is not worth it and the sequential path runs instead.
	jsonlConcurrentMinBytes = 1 << 20 // 1MiB
	// jsonlShardTargetBytes is the rough content size per shard.
	jsonlShardTargetBytes = 1 << 20 // 1MiB
)

// jsonlContentConcurrent is jsonlContentImpl with the line-by-line pass sharded
// across goroutines. Output is byte-identical to the sequential path because
// redactJSONLLines treats every line independently and shards are contiguous
// line ranges rejoined in order.
//
// redactor MUST be safe for concurrent use. String is (it is a pure function of
// its argument, and the layer config it reads is guarded by sync.Once/RWMutex,
// while betterleaks' Detect path does not mutate the shared detector). The OPF
// flow's collector closure is NOT — it accumulates into a shared map and slice —
// so JSONLContentWithPrivacyFilter deliberately stays on jsonlContentImpl.
func jsonlContentConcurrent(content string, redactor func(string) string) (string, error) {
	if result, handled, err := redactSingleJSONValue(content, redactor); handled {
		return result, err
	}

	lines := strings.Split(content, "\n")
	shardCount := len(content) / jsonlShardTargetBytes
	if len(content) < jsonlConcurrentMinBytes || shardCount < 2 || len(lines) < 2 {
		return redactJSONLLines(lines, redactor)
	}
	shardCount = min(shardCount, len(lines))

	linesPerShard := (len(lines) + shardCount - 1) / shardCount
	type shard struct {
		lo, hi int
	}
	shards := make([]shard, 0, shardCount)
	for lo := 0; lo < len(lines); lo += linesPerShard {
		shards = append(shards, shard{lo: lo, hi: min(lo+linesPerShard, len(lines))})
	}

	results := make([]string, len(shards))
	g := new(errgroup.Group)
	g.SetLimit(runtime.GOMAXPROCS(0))
	for i, s := range shards {
		g.Go(func() error {
			out, err := redactJSONLLines(lines[s.lo:s.hi], redactor)
			if err != nil {
				return err
			}
			results[i] = out
			return nil
		})
	}
	if err := g.Wait(); err != nil {
		return "", err
	}

	// Shards are contiguous line ranges, so rejoining them with "\n" in order
	// reproduces the sequential join exactly.
	return strings.Join(results, "\n"), nil
}

