// CommonDir returns the git common directory for the worktree repo was opened
// from — the same directory `git rev-parse --git-common-dir` reports, so linked
// worktrees resolve to the shared parent rather than their own .git/worktrees
// entry. Callers use it to place git-internal state that must be shared across
// worktrees and must not live inside the working tree.
//
// Returns an error for bare repositories, which have no worktree to resolve.
func CommonDir(repo *git.Repository) (string, error) {
	worktree, err := repo.Worktree()
	if err != nil {
		return "", fmt.Errorf("resolve worktree: %w", err)
	}
