// redactCacheHolder resolves the redaction prefix cache for a repository once
// per store. Resolution touches the filesystem, so it is deferred until a write
// path actually needs it and never repeated.
type redactCacheHolder struct {
	once  sync.Once
	cache *redactCache
}

// get returns the cache for repo, or nil when the git common directory cannot be
// resolved (a bare repository, for instance). A nil result disables incremental
// reuse without failing the write.
func (h *redactCacheHolder) get(repo *git.Repository) *redactCache {
	h.once.Do(func() {
		dir, err := gitrepo.CommonDir(repo)
		if err != nil {
			return
		}
		h.cache = newRedactCache(dir)
	})
	return h.cache
}
