func TestBenchSessionGrowth(t *testing.T) {
	rng := rand.New(rand.NewSource(11))
	blob := make([]byte, 24*1024)
	appendChunk := func(b *strings.Builder, target int) {
		start := b.Len()
		for b.Len()-start < target {
			rng.Read(blob)
			line, _ := json.Marshal(map[string]any{
				"type": "response_item",
				"payload": map[string]any{
					"type":              "reasoning",
					"encrypted_content": base64.StdEncoding.EncodeToString(blob),
					"note":              "REDACTED and the quick brown fox jumps over the lazy dog",
				},
			})
			b.Write(line)
			b.WriteByte('\n')
		}
	}
	const checkpoints = 14
	const perCheckpoint = 5 << 20
	for _, incremental := range []bool{false, true} {
		repo, dir := newTestRepoForCache(t)
		var cache *redactCache
		if incremental {
			cache = newRedactCache(filepath.Join(dir, ".git"))
		}
		var content strings.Builder
		path := filepath.Join(dir, "full.jsonl")
		var total, last time.Duration
		for range checkpoints {
			appendChunk(&content, perCheckpoint)
			if err := os.WriteFile(path, []byte(content.String()), 0o600); err != nil {
				t.Fatal(err)
			}
			t0 := time.Now()
			if _, _, err := createRedactedBlobFromFile(context.Background(), repo, cache, path, "full.jsonl"); err != nil {
				t.Fatal(err)
			}
			last = time.Since(t0)
			total += last
		}
		label := "full re-redaction (before)"
		if incremental {
			label = "incremental (after)   "
		}
		fmt.Printf("%s  final=%dMB  last Stop=%-9s cumulative=%s\n",
			label, content.Len()>>20, last.Round(time.Millisecond), total.Round(time.Millisecond))
	}
}
